window.products.push({"id":536567,"name":"VetGun Delivery System","category":"homeandappliances","retail price":339.56,"sale price":null,"image":"https://m.media-amazon.com/images/I/51zFkG4GwBL._AC_SL1200_.jpg","description":"VetGun Delivery System VetGun delivery system removes the hassle, stress and danger associated with working cattle to control parasites. Quick convenient dosing technique provides an easy way to dose your entire herd while they are in the field. Removes the need for expensive handling facilities and reduces labor requirement up to 75%. VetGun fires VetCaps to range of 30 feet with VetCap bursting on cow releasing its contents. Formulation goes to work in a similar way to pour-on products. Features: Includes two adaptors to use with 25 gram or 90 gram CO2 propellant cartridges Fire VetCaps out to range of 30 feet Reduces stress on animal and minimizes discomfort compared to other dosing methods Item Specifications: Dosing: 1 capsule for Cattle greater than 600 lbs Kit does not come with VetCaps or CO2 Cartridges","images":["https://m.media-amazon.com/images/I/51zFkG4GwBL._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Agrilabs","source_asin":"B00L2G5RSG","category_path":"Home & Kitchen"},"sku":"BM-536567","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00L2G5RSG","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00L2G5RSG","price_pending":true,"merchant_ready":false});
